,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fetch ISBN '
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  IF :P15_ISBN IS NOT NULL THEN',
'    BEGIN',
'      SELECT ISBN INTO :P15_ISBN',
'      FROM BOOK',
'      WHERE ISBN = :P15_ISBN;',
'    EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'        NULL;',
'    END;',
'  END IF;',
'END;',
'',
''))
